-- MTF Nu-7 "Hammer Down" database schema (PostgreSQL / Supabase)
-- Load order: schema.sql, then data.sql (generated by import_nu7.py), then policies.sql.
-- Columns ending in _raw keep the original sheet text when a person or rank could not be matched.

-- ===== Core =====
create table rank_category (
  id int primary key,
  name text not null unique,
  sort_order int not null
);

create table rank (
  id int primary key,
  code text not null unique,                    -- PVT, SPC, LCPL, CPL, SGT, CSG, LT, CPT, MAJ, LTCOM, COM
  name text not null,
  category_id int not null references rank_category,
  sort_order int not null,                      -- 1 = PVT ... 11 = COM
  max_slots int,
  weekly_hours_required numeric(4,1) not null default 6,
  cooldown_days int not null default 7
);

create table person (
  id uuid primary key default gen_random_uuid(),
  steam_id text unique check (steam_id ~ '^STEAM_0:[01]:[0-9]+$'),  -- null only for legacy entries
  discord_username text,
  display_name text not null,
  created_at timestamptz not null default now()
);

create table person_alias (
  person_id uuid not null references person on delete cascade,
  name text not null,
  first_seen date,
  primary key (person_id, name)
);

create table membership (
  id uuid primary key default gen_random_uuid(),
  person_id uuid not null references person,
  rank_id int not null references rank,
  recruited_at date,
  left_at date,                                 -- null = currently serving
  discharge_type text check (discharge_type in ('honourable','dishonourable')),
  discharge_reason text,
  discharged_by uuid references person,
  discharged_by_raw text,
  status_override text,                         -- statuses that cannot be calculated, e.g. 'Touch Grass'
  notes text
);
create unique index one_active_membership on membership (person_id) where left_at is null;

-- ===== Requirements =====
create table qualification (
  id int primary key,
  name text not null unique
);

create table person_qualification (
  person_id uuid not null references person on delete cascade,
  qualification_id int not null references qualification,
  granted_at date not null default current_date,
  primary key (person_id, qualification_id)
);

create table requirement (
  id int primary key,
  from_rank_id int not null references rank,     -- applies to promotion FROM this rank
  title text not null,
  kind text not null check (kind in
    ('manual','qualification','activity','hosted_training','hosted_tryout','attended_basic','cooldown')),
  qualification_id int references qualification,
  params jsonb not null default '{}',
  sort_order int not null default 0,
  is_active boolean not null default true
);

create table member_requirement (
  membership_id uuid not null references membership on delete cascade,
  requirement_id int not null references requirement on delete cascade,
  done boolean not null default false,
  done_at timestamptz,
  note text,
  primary key (membership_id, requirement_id)
);

-- ===== Logs =====
create table duty_log (
  id bigint generated by default as identity primary key,
  person_id uuid not null references person,
  logged_on date not null,
  hours numeric(5,1) not null check (hours >= 0),
  rank_id int references rank,
  rank_raw text,
  comment text,
  source text not null default 'officer' check (source in ('officer', 'self', 'import')),
  rejected boolean not null default false,       -- set by an officer; rejected hours do not count
  logged_at timestamptz not null default now()
);
create index duty_log_person_day on duty_log (person_id, logged_on);

create table training_type (
  id int primary key,
  name text not null unique,
  is_basic_training boolean not null default false
);

create table training (
  id bigint generated by default as identity primary key,
  host_id uuid references person,
  host_raw text,
  type_id int not null references training_type,
  held_on date not null,
  description text,
  comment text
);

create table training_attendee (
  training_id bigint not null references training on delete cascade,
  person_id uuid references person,
  raw_name text not null
);
create unique index training_attendee_unique on training_attendee (training_id, person_id) where person_id is not null;

create table tryout (
  id bigint generated by default as identity primary key,
  recruit_id uuid not null references person,
  host_id uuid references person,
  host_raw text,
  held_on date not null,
  result text not null check (result in ('passed','failed')),
  strikes numeric(3,1) not null default 0,
  comment text
);

create table tryout_quiz (
  tryout_id bigint primary key references tryout on delete cascade,
  taken_at timestamp,
  score int,
  max_score int,
  answers jsonb not null default '{}'
);

create table rank_change (
  id bigint generated by default as identity primary key,
  person_id uuid not null references person,
  from_rank_id int references rank,
  to_rank_id int not null references rank,
  kind text not null check (kind in ('promoted','demoted','bookkeeping')),
  effective_on date not null,
  officer_id uuid references person,
  officer_raw text,
  comment text
);
create index rank_change_person_day on rank_change (person_id, effective_on desc);

create table strike (
  id bigint generated by default as identity primary key,
  person_id uuid not null references person,
  weight numeric(3,1) not null check (weight >= 0),
  reason text,
  issued_on date not null,
  expires_on date,
  officer_id uuid references person,
  officer_raw text,
  appeal_status text not null default 'none' check (appeal_status in ('none','pending','granted','denied')),
  appealable_to text,
  appeal_reason text
);

create table infraction (
  id bigint generated by default as identity primary key,
  person_id uuid not null references person,
  issued_on date not null,
  reason text,
  punishment text,
  officer_id uuid references person,
  officer_raw text,
  executed boolean not null default false,
  executed_by uuid references person,
  executed_by_raw text,
  becomes_strike_on date,
  appeal_status text
);

create table leave (
  id bigint generated by default as identity primary key,
  person_id uuid not null references person,
  type text not null check (type in ('LOA','ROA')),
  requested_on date,
  starts_on date not null,
  ends_on date not null check (ends_on >= starts_on),
  reason text,
  approved_by uuid references person,
  approved_by_raw text,
  officer_note text
);

-- ===== Organisation & honours =====
create table blacklist (
  id bigint generated by default as identity primary key,
  person_id uuid not null references person,
  reason text,
  appealable_to text,
  officer_id uuid references person,
  officer_raw text,
  issued_on date not null,
  expires_on date                               -- null = appeal only
);

create table blacklist_appeal (
  id bigint generated by default as identity primary key,
  blacklist_id bigint not null references blacklist on delete cascade,
  appealed_on date,
  decision text not null default 'pending' check (decision in ('pending','revoked','denied')),
  decided_on date,
  decided_by uuid references person,
  decided_by_raw text,
  reason text
);

create table medal_type (
  id int primary key,
  name text not null unique,
  family text not null,
  grade text,
  criteria text
);

create table medal_award (
  id bigint generated by default as identity primary key,
  person_id uuid not null references person,
  medal_type_id int not null references medal_type,
  awarded_on date,
  issuer_id uuid references person,
  issuer_raw text
);

create table battalion (
  id int primary key,
  name text not null unique,
  specialisation text,
  min_rank_id int references rank
);

create table battalion_member (
  battalion_id int not null references battalion,
  person_id uuid not null references person,
  primary key (battalion_id, person_id)
);

create table unit (
  id int primary key,
  name text not null unique,
  lead_min_rank_id int references rank,
  assistant_min_rank_id int references rank
);

create table unit_role (
  unit_id int not null references unit,
  person_id uuid not null references person,
  role text not null check (role in ('lead','assistant')),
  primary key (unit_id, person_id)
);

create table fund_transaction (
  id bigint generated by default as identity primary key,
  person_id uuid references person,
  amount numeric(12,2) not null,
  reason text,
  booked_on date
);

create table memorial_entry (
  id int primary key,
  person_id uuid references person,
  section text not null,
  rank_code text,
  name text not null,
  quote text
);

-- ===== Audit trail =====
create table audit_log (
  id bigint generated by default as identity primary key,
  table_name text not null,
  action text not null,
  old_data jsonb,
  new_data jsonb,
  actor uuid,                                   -- Supabase login that made the change (null = database admin or hours form)
  at timestamptz not null default now()
);

create function audit_change() returns trigger
language plpgsql security definer set search_path = public, pg_temp as $$
begin
  insert into audit_log (table_name, action, actor, old_data, new_data)
  values (tg_table_name, tg_op, auth.uid(),
          case when tg_op <> 'INSERT' then to_jsonb(old) end,
          case when tg_op <> 'DELETE' then to_jsonb(new) end);
  return coalesce(new, old);
end $$;

-- ===== Settings for calculated values =====
create table setting (
  key text primary key,
  value numeric not null,
  description text
);
insert into setting values
  ('activity_window_days', 7, 'Duty hours are summed over this many days'),
  ('very_active_hours', 25, 'From this many hours a member counts as Very-Active'),
  ('extremely_active_hours', 30, 'From this many hours a member counts as Extremely-Active');

-- "Today" for every calculation. A session can pin it (set nu7.today = '2026-11-02') to compare with an old export.
create function app_today() returns date language sql stable as $$
  select coalesce(nullif(current_setting('nu7.today', true), '')::date, current_date)
$$;

-- ===== Views =====
create view v_active_blacklist with (security_invoker = true) as
select b.*, p.steam_id, p.display_name
from blacklist b join person p on p.id = b.person_id
where (b.expires_on is null or b.expires_on > app_today())
  and not exists (select 1 from blacklist_appeal a where a.blacklist_id = b.id and a.decision = 'revoked');

create view v_roster with (security_invoker = true) as
select m.id as membership_id, p.id as person_id, p.display_name, p.steam_id,
       r.id as rank_id, r.code as rank, r.name as rank_name, r.sort_order as rank_order,
       rc.id as category_id, rc.name as category,
       coalesce(s.points, 0)                                            as strikes,
       coalesce(d.hours, 0)                                             as hours,
       r.weekly_hours_required,
       greatest(r.weekly_hours_required - coalesce(d.hours, 0), 0)      as hours_remaining,
       lp.last_change                                                   as last_promotion,
       coalesce(lp.last_change + r.cooldown_days > app_today(), false)  as on_cooldown,
       lv.type as leave_type, lv.ends_on as leave_ends_on,
       coalesce(m.status_override, lv.type,
         case when r.weekly_hours_required = 0 and coalesce(d.hours, 0) < (select value from setting where key = 'very_active_hours') then 'Active'
              when coalesce(d.hours, 0) = 0 then 'Inactive'
              when d.hours < r.weekly_hours_required then 'Semi-Active'
              when d.hours < (select value from setting where key = 'very_active_hours') then 'Active'
              when d.hours < (select value from setting where key = 'extremely_active_hours') then 'Very-Active'
              else 'Extremely-Active' end)                              as status,
       m.recruited_at, m.notes, m.status_override,
       (select count(*) from medal_award ma where ma.person_id = p.id)  as medals
from membership m
join person p on p.id = m.person_id
join rank r on r.id = m.rank_id
join rank_category rc on rc.id = r.category_id
left join lateral (select sum(weight) as points from strike
  where person_id = p.id and (expires_on is null or expires_on > app_today()) and appeal_status <> 'granted') s on true
-- last N full days plus today (matches the sheet's Hours column, which had no entries for its export day)
left join lateral (select sum(hours) as hours from duty_log
  where person_id = p.id and not rejected and logged_on <= app_today()
    and logged_on >= app_today() - (select value::int from setting where key = 'activity_window_days')) d on true
-- last promotion, rank bookkeeping or (re)recruitment, whichever is latest
left join lateral (select greatest(max(effective_on), m.recruited_at) as last_change from rank_change
  where person_id = p.id and kind in ('promoted','bookkeeping')) lp on true
left join lateral (select type, ends_on from leave
  where person_id = p.id and app_today() between starts_on and ends_on order by starts_on desc limit 1) lv on true
where m.left_at is null;

-- One row per serving member and active requirement of their rank.
-- met = ticked by an officer, or fulfilled automatically from the logs.
-- Activity and cooldown change over time, so only the calculation counts for them, never a tick.
create view v_promotion_board with (security_invoker = true) as
select b.*, case when b.kind in ('activity', 'cooldown') then b.auto_met else b.ticked or b.auto_met end as met
from (
select ro.membership_id, ro.person_id, ro.display_name, ro.steam_id, ro.rank, ro.rank_id, ro.status, ro.strikes,
       ro.hours, ro.weekly_hours_required, ro.on_cooldown,
       q.id as requirement_id, q.title, q.kind, q.sort_order,
       coalesce(mr.done, false) as ticked,
       case q.kind
         when 'activity' then ro.hours >= ro.weekly_hours_required
         when 'cooldown' then not ro.on_cooldown
         when 'qualification' then exists (select 1 from person_qualification pq
                                 where pq.person_id = ro.person_id and pq.qualification_id = q.qualification_id)
         when 'attended_basic' then exists (select 1 from training_attendee ta
                                 join training t on t.id = ta.training_id
                                 join training_type tt on tt.id = t.type_id
                                 where ta.person_id = ro.person_id and tt.is_basic_training)
         when 'hosted_training' then (select count(*) from training t where t.host_id = ro.person_id
                                 and t.held_on > app_today() - coalesce((q.params->>'days')::int, 14))
                                 >= coalesce((q.params->>'count')::int, 1)
         when 'hosted_tryout' then (select count(*) from tryout tr where tr.host_id = ro.person_id)
                                 >= coalesce((q.params->>'count')::int, 1)
         else false
       end as auto_met
from v_roster ro
join requirement q on q.from_rank_id = ro.rank_id and q.is_active
left join member_requirement mr on mr.membership_id = ro.membership_id and mr.requirement_id = q.id
) b;

create view v_overview with (security_invoker = true) as
select
  (select count(*) from v_roster)                                         as members,
  (select sum(max_slots) from rank)                                       as slots,
  (select count(*) from v_roster where status in ('Active','Very-Active','Extremely-Active','Touch Grass')) as active,
  (select count(*) from v_roster where status = 'Semi-Active')            as semi_active,
  (select count(*) from v_roster where status = 'Inactive')               as inactive,
  (select count(*) from v_roster where status = 'LOA')                    as on_loa,
  (select count(*) from v_roster where status = 'ROA')                    as on_roa,
  (select coalesce(sum(amount), 0) from fund_transaction)                 as fund_balance,
  (select count(*) from training where held_on > app_today() - 7)        as trainings_7d,
  (select count(*) from tryout where held_on > app_today() - 7)          as tryouts_7d;
